import { caseOutcome,enteredThisWeek,matchesCaseSearch } from './case-query.js';
import { DESTINATIONS } from './engine.js';

export function outcomeStats(cases) {
  const result={total:cases.length,accepted:0,rejected:0,cancelled:0,pending:0};
  for(const r of cases)result[caseOutcome(r)]++;
  result.decided=result.accepted+result.rejected;
  result.acceptanceRate=result.decided?result.accepted/result.decided*100:null;
  result.rejectionRate=result.decided?result.rejected/result.decided*100:null;
  return result;
}
export function renderOutcomes({cases,query='',weekOnly=false,person=()=>null,escape:e}) {
  const list=cases.filter(r=>matchesCaseSearch(r,query,person(r.ownerId))&&(!weekOnly||enteredThisWeek(r))),stats=outcomeStats(list);
  const percent=value=>value==null?'—':value.toFixed(1)+'%';
  const groups=new Map();for(const r of list){const country=r.country||DESTINATIONS[r.kind]||'Unspecified';if(!groups.has(country))groups.set(country,[]);groups.get(country).push(r);}
  const countries=[...groups].map(([name,rows])=>({name,...outcomeStats(rows)})).sort((a,b)=>b.decided-a.decided||a.name.localeCompare(b.name));
  const metric=(label,value,foot,kind='')=>`<div class="metric ${kind}"><div class="metric-top">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;
  return `<div class="outcome-scope"><span class="badge neutral">${stats.total} cases in this view</span><span>${weekOnly?'Files entered this week':'All accessible files'}${query?' · Search applied':''}</span></div><div class="metrics outcome-metrics">${metric('Acceptance rate',percent(stats.acceptanceRate),`${stats.accepted} accepted cases`,'accepted-metric')}${metric('Rejection rate',percent(stats.rejectionRate),`${stats.rejected} rejected cases`,'rejected-metric')}${metric('Recorded decisions',stats.decided,'Accepted + rejected')}${metric('No recorded decision',stats.pending,`${stats.cancelled} cancelled · excluded from rates`)}</div><div class="outcomes-grid"><section class="panel outcome-summary"><div class="panel-head"><div><h2>Visa decisions</h2><p>Acceptance and rejection among cases with a recorded decision.</p></div></div><div class="outcome-body">${stats.decided?`<div class="decision-bar" role="img" aria-label="${stats.accepted} accepted (${percent(stats.acceptanceRate)}), ${stats.rejected} rejected (${percent(stats.rejectionRate)})"><span class="decision-accepted" style="width:${stats.acceptanceRate}%"></span><span class="decision-rejected" style="width:${stats.rejectionRate}%"></span></div><div class="decision-legend"><p><span class="legend-dot accepted-dot"></span><strong>${stats.accepted}</strong> accepted <small>${percent(stats.acceptanceRate)}</small></p><p><span class="legend-dot rejected-dot"></span><strong>${stats.rejected}</strong> rejected <small>${percent(stats.rejectionRate)}</small></p></div>`:'<div class="empty"><h3>No decisions recorded yet.</h3><p>Rates appear when a case is marked Accepted or Rejected.</p></div>'}<p class="outcome-formula">Acceptance = accepted ÷ (accepted + rejected). Rejection uses the same denominator. Cases without a decision and cancelled cases are excluded.</p></div></section><section class="panel"><div class="panel-head"><div><h2>By country</h2><p>Recorded decisions for the cases in this view.</p></div></div><div class="country-outcomes">${countries.map(c=>`<article class="country-outcome"><div class="country-outcome-heading"><h3>${e(c.name)}</h3><span>${c.decided} decisions · ${c.total} cases</span></div><div class="country-decision-track" role="img" aria-label="${e(c.name)}: ${c.accepted} accepted and ${c.rejected} rejected"><span class="decision-accepted" style="width:${c.acceptanceRate||0}%"></span><span class="decision-rejected" style="width:${c.rejectionRate||0}%"></span></div><div class="country-outcome-counts"><span>Accepted <strong>${c.accepted}</strong> · ${percent(c.acceptanceRate)}</span><span>Rejected <strong>${c.rejected}</strong> · ${percent(c.rejectionRate)}</span></div></article>`).join('')||'<div class="empty"><h3>No matching cases.</h3><p>Clear the search or turn off This week to see more cases.</p></div>'}</div></section></div>`;
}
